INSERT INTO `prompt_templates` (`id`, `taskType`, `language`, `name`, `description`, `template`, `systemPrompt`, `variables`, `version`, `parentTemplateId`, `config`, `isEnabled`, `priority`, `statistics`, `effectiveness`, `tags`, `category`, `examples`, `metadata`, `createdBy`, `updatedBy`, `createdAt`, `updatedAt`) VALUES (1,'title_generation','zh-CN','文章标题生成（中文）','根据文章内容生成吸引人的标题','请根据以下文章内容，生成一个简洁、吸引人、突出重点的标题（不超过30个字）：\n\n{{content}}\n\n要求：\n1. 标题要准确概括文章主题\n2. 使用简洁有力的语言\n3. 避免使用标点符号\n4. 只返回标题文本，不要解释','你是一位专业的内容编辑，擅长创作吸引人的文章标题。','[{\"name\":\"content\",\"type\":\"string\",\"required\":true,\"description\":\"文章内容\"}]','1.0.0',NULL,'{\"maxLength\":100,\"temperature\":0.8,\"topP\":0.9}',1,10,'{\"usageCount\":0,\"successCount\":0,\"failureCount\":0,\"averageScore\":0,\"lastUsedAt\":null}','{\"qualityScore\":0,\"relevanceScore\":0,\"userSatisfaction\":0,\"adoptionRate\":0}','[\"title\",\"chinese\",\"content-generation\"]',NULL,'[]','{}',NULL,NULL,'2025-10-10 12:13:10','2025-10-10 12:13:10');
INSERT INTO `prompt_templates` (`id`, `taskType`, `language`, `name`, `description`, `template`, `systemPrompt`, `variables`, `version`, `parentTemplateId`, `config`, `isEnabled`, `priority`, `statistics`, `effectiveness`, `tags`, `category`, `examples`, `metadata`, `createdBy`, `updatedBy`, `createdAt`, `updatedAt`) VALUES (2,'tag_extraction','zh-CN','标签提取（中文）','从文章内容中提取关键标签','请从以下文章内容中提取3-5个最相关的标签：\n\n{{content}}\n\n要求：\n1. 标签要准确反映文章主题和关键词\n2. 每个标签2-6个字\n3. 标签之间用逗号分隔\n4. 只返回标签列表，不要解释\n5. 格式示例：技术,编程,Python,人工智能,机器学习','你是一位专业的内容分析师，擅长从文章中提取关键标签。','[{\"name\":\"content\",\"type\":\"string\",\"required\":true,\"description\":\"文章内容\"}]','1.0.0',NULL,'{\"temperature\":0.5,\"topP\":0.9}',1,10,'{\"usageCount\":0,\"successCount\":0,\"failureCount\":0,\"averageScore\":0,\"lastUsedAt\":null}','{\"qualityScore\":0,\"relevanceScore\":0,\"userSatisfaction\":0,\"adoptionRate\":0}','[\"tag\",\"chinese\",\"extraction\"]',NULL,'[]','{}',NULL,NULL,'2025-10-10 12:13:10','2025-10-10 12:13:10');
INSERT INTO `prompt_templates` (`id`, `taskType`, `language`, `name`, `description`, `template`, `systemPrompt`, `variables`, `version`, `parentTemplateId`, `config`, `isEnabled`, `priority`, `statistics`, `effectiveness`, `tags`, `category`, `examples`, `metadata`, `createdBy`, `updatedBy`, `createdAt`, `updatedAt`) VALUES (3,'summary_generation','zh-CN','摘要生成（中文）','生成文章摘要','请为以下文章生成一个100-200字的摘要：\n\n{{content}}\n\n要求：\n1. 概括文章的核心内容和要点\n2. 使用简洁流畅的语言\n3. 保持客观中立的态度\n4. 只返回摘要文本，不要解释','你是一位专业的内容编辑，擅长概括文章要点。','[{\"name\":\"content\",\"type\":\"string\",\"required\":true,\"description\":\"文章内容\"}]','1.0.0',NULL,'{\"maxLength\":300,\"temperature\":0.7,\"topP\":0.9}',1,10,'{\"usageCount\":0,\"successCount\":0,\"failureCount\":0,\"averageScore\":0,\"lastUsedAt\":null}','{\"qualityScore\":0,\"relevanceScore\":0,\"userSatisfaction\":0,\"adoptionRate\":0}','[\"summary\",\"chinese\",\"content-generation\"]',NULL,'[]','{}',NULL,NULL,'2025-10-10 12:13:10','2025-10-10 12:13:10');
INSERT INTO `prompt_templates` (`id`, `taskType`, `language`, `name`, `description`, `template`, `systemPrompt`, `variables`, `version`, `parentTemplateId`, `config`, `isEnabled`, `priority`, `statistics`, `effectiveness`, `tags`, `category`, `examples`, `metadata`, `createdBy`, `updatedBy`, `createdAt`, `updatedAt`) VALUES (4,'title_generation','en-US','Article Title Generation (English)','Generate attractive titles based on article content','Please generate a concise, attractive title (no more than 60 characters) based on the following article content:\n\n{{content}}\n\nRequirements:\n1. Accurately summarize the article\'s theme\n2. Use concise and powerful language\n3. Avoid using punctuation\n4. Return only the title text without explanation','You are a professional content editor skilled in creating attractive article titles.','[{\"name\":\"content\",\"type\":\"string\",\"required\":true,\"description\":\"Article content\"}]','1.0.0',NULL,'{\"maxLength\":100,\"temperature\":0.8,\"topP\":0.9}',1,10,'{\"usageCount\":0,\"successCount\":0,\"failureCount\":0,\"averageScore\":0,\"lastUsedAt\":null}','{\"qualityScore\":0,\"relevanceScore\":0,\"userSatisfaction\":0,\"adoptionRate\":0}','[\"title\",\"english\",\"content-generation\"]',NULL,'[]','{}',NULL,NULL,'2025-10-10 12:13:10','2025-10-10 12:13:10');
INSERT INTO `prompt_templates` (`id`, `taskType`, `language`, `name`, `description`, `template`, `systemPrompt`, `variables`, `version`, `parentTemplateId`, `config`, `isEnabled`, `priority`, `statistics`, `effectiveness`, `tags`, `category`, `examples`, `metadata`, `createdBy`, `updatedBy`, `createdAt`, `updatedAt`) VALUES (5,'tag_extraction','en-US','Tag Extraction (English)','Extract key tags from article content','Please extract 5-8 most relevant tags from the following article content:\n\n{{content}}\n\nRequirements:\n1. Tags should accurately reflect the article\'s theme and keywords\n2. Each tag should be 2-15 characters\n3. Separate tags with commas\n4. Return only the tag list without explanation\n5. Example format: technology,programming,python,ai,machine-learning','You are a professional content analyst skilled in extracting key tags from articles.','[{\"name\":\"content\",\"type\":\"string\",\"required\":true,\"description\":\"Article content\"}]','1.0.0',NULL,'{\"temperature\":0.5,\"topP\":0.9}',1,10,'{\"usageCount\":0,\"successCount\":0,\"failureCount\":0,\"averageScore\":0,\"lastUsedAt\":null}','{\"qualityScore\":0,\"relevanceScore\":0,\"userSatisfaction\":0,\"adoptionRate\":0}','[\"tag\",\"english\",\"extraction\"]',NULL,'[]','{}',NULL,NULL,'2025-10-10 12:13:10','2025-10-10 12:13:10');
INSERT INTO `prompt_templates` (`id`, `taskType`, `language`, `name`, `description`, `template`, `systemPrompt`, `variables`, `version`, `parentTemplateId`, `config`, `isEnabled`, `priority`, `statistics`, `effectiveness`, `tags`, `category`, `examples`, `metadata`, `createdBy`, `updatedBy`, `createdAt`, `updatedAt`) VALUES (6,'summary_generation','en-US','Summary Generation (English)','Generate article summary','Please generate a 100-200 word summary for the following article:\n\n{{content}}\n\nRequirements:\n1. Summarize the core content and key points\n2. Use concise and fluent language\n3. Maintain an objective and neutral attitude\n4. Return only the summary text without explanation','You are a professional content editor skilled in summarizing article key points.','[{\"name\":\"content\",\"type\":\"string\",\"required\":true,\"description\":\"Article content\"}]','1.0.0',NULL,'{\"maxLength\":300,\"temperature\":0.7,\"topP\":0.9}',1,10,'{\"usageCount\":0,\"successCount\":0,\"failureCount\":0,\"averageScore\":0,\"lastUsedAt\":null}','{\"qualityScore\":0,\"relevanceScore\":0,\"userSatisfaction\":0,\"adoptionRate\":0}','[\"summary\",\"english\",\"content-generation\"]',NULL,'[]','{}',NULL,NULL,'2025-10-10 12:13:10','2025-10-10 12:13:10');
INSERT INTO `prompt_templates` (`id`, `taskType`, `language`, `name`, `description`, `template`, `systemPrompt`, `variables`, `version`, `parentTemplateId`, `config`, `isEnabled`, `priority`, `statistics`, `effectiveness`, `tags`, `category`, `examples`, `metadata`, `createdBy`, `updatedBy`, `createdAt`, `updatedAt`) VALUES (10,'category_matching','zh-CN','分类匹配','智能匹配文章分类','你是一个专业的内容分类助手，擅长根据文章内容匹配最合适的分类。请必须选择一个最匹配的，分类不允许为空\n\n可用分类列表：\n{{#each categories}}\n- {{this.name}}: {{this.description}}\n{{/each}}\n\n请分析以下文章内容：\n\n{{content}}\n\n要求：\n1. 选择最匹配的分类（1-3个）\n2. 基于文章核心内容判断\n3. 优先选择主要分类\n4. 考虑文章的专业领域\n\n请直接输出分类名称，用逗号分隔。',NULL,'[{\"name\":\"content\",\"type\":\"string\",\"required\":true,\"description\":\"文章内容\"},{\"name\":\"categories\",\"type\":\"array\",\"required\":true,\"description\":\"可用分类列表\"}]','1.0.0',NULL,'{}',1,10,'{\"usageCount\":0,\"successCount\":0,\"failureCount\":0,\"averageScore\":0,\"lastUsedAt\":null}','{\"qualityScore\":0,\"relevanceScore\":0,\"userSatisfaction\":0,\"adoptionRate\":0}','[\"classification\",\"content\",\"ai\"]','content_analysis','[{\"input\":{\"content\":\"React Hooks 是 React 16.8 引入的新特性...\",\"categories\":[{\"name\":\"前端开发\",\"description\":\"HTML, CSS, JavaScript 等\"},{\"name\":\"后端开发\",\"description\":\"服务器端开发\"},{\"name\":\"移动开发\",\"description\":\"iOS, Android 开发\"}]},\"output\":\"前端开发\"}]','{}',NULL,NULL,'2025-10-16 13:01:56','2025-10-16 13:01:56');
INSERT INTO `prompt_templates` (`id`, `taskType`, `language`, `name`, `description`, `template`, `systemPrompt`, `variables`, `version`, `parentTemplateId`, `config`, `isEnabled`, `priority`, `statistics`, `effectiveness`, `tags`, `category`, `examples`, `metadata`, `createdBy`, `updatedBy`, `createdAt`, `updatedAt`) VALUES (11,'seo_optimization','zh-CN','SEO 优化建议','提供文章 SEO 优化建议','你是一个专业的 SEO 优化顾问，擅长分析内容并提供 SEO 优化建议。\n\n请分析以下文章：\n\n标题：{{title}}\n内容：{{content}}\n{{#if keywords}}目标关键词：{{keywords}}{{/if}}\n\n请提供 SEO 优化建议，包括：\n1. 关键词密度分析\n2. 标题优化建议\n3. 元描述建议\n4. 内链外链建议\n5. 内容结构优化\n\n请以 JSON 格式输出建议：\n{\n  \"keywordDensity\": \"关键词密度评估\",\n  \"titleSuggestion\": \"标题优化建议\",\n  \"metaDescription\": \"元描述建议\",\n  \"linkSuggestions\": \"链接建议\",\n  \"structureTips\": \"结构优化建议\",\n  \"score\": \"SEO 得分（1-100）\"\n}',NULL,'[{\"name\":\"title\",\"type\":\"string\",\"required\":true,\"description\":\"文章标题\"},{\"name\":\"content\",\"type\":\"string\",\"required\":true,\"description\":\"文章内容\"},{\"name\":\"keywords\",\"type\":\"string\",\"required\":false,\"description\":\"目标关键词\"}]','1.0.0',NULL,'{}',1,10,'{\"usageCount\":0,\"successCount\":0,\"failureCount\":0,\"averageScore\":0,\"lastUsedAt\":null}','{\"qualityScore\":0,\"relevanceScore\":0,\"userSatisfaction\":0,\"adoptionRate\":0}','[\"seo\",\"optimization\",\"content\"]','content_optimization','[]','{}',NULL,NULL,'2025-10-18 05:30:57','2025-10-18 05:30:57');
INSERT INTO `prompt_templates` (`id`, `taskType`, `language`, `name`, `description`, `template`, `systemPrompt`, `variables`, `version`, `parentTemplateId`, `config`, `isEnabled`, `priority`, `statistics`, `effectiveness`, `tags`, `category`, `examples`, `metadata`, `createdBy`, `updatedBy`, `createdAt`, `updatedAt`) VALUES (12,'content_quality_check','zh-CN','内容质量评估','评估文章内容质量','你是一个专业的内容质量评估专家，擅长从多个维度分析文章质量。\n\n请评估以下文章：\n\n标题：{{title}}\n内容：{{content}}\n\n评估维度：\n1. 内容原创性（是否有价值、是否独特）\n2. 逻辑结构（结构是否清晰、层次是否分明）\n3. 语言表达（语言是否流畅、是否有错别字）\n4. 专业深度（内容是否专业、是否有深度）\n5. 可读性（是否易读、是否吸引人）\n6. 实用性（是否有实用价值）\n\n请以 JSON 格式输出评估结果：\n{\n  \"originality\": {\"score\": 0-100, \"comment\": \"评价\"},\n  \"structure\": {\"score\": 0-100, \"comment\": \"评价\"},\n  \"language\": {\"score\": 0-100, \"comment\": \"评价\"},\n  \"depth\": {\"score\": 0-100, \"comment\": \"评价\"},\n  \"readability\": {\"score\": 0-100, \"comment\": \"评价\"},\n  \"practicality\": {\"score\": 0-100, \"comment\": \"评价\"},\n  \"overallScore\": 0-100,\n  \"overallComment\": \"总体评价\",\n  \"improvements\": [\"改进建议1\", \"改进建议2\"]\n}',NULL,'[{\"name\":\"title\",\"type\":\"string\",\"required\":true,\"description\":\"文章标题\"},{\"name\":\"content\",\"type\":\"string\",\"required\":true,\"description\":\"文章内容\"}]','1.0.0',NULL,'{}',1,10,'{\"usageCount\":0,\"successCount\":0,\"failureCount\":0,\"averageScore\":0,\"lastUsedAt\":null}','{\"qualityScore\":0,\"relevanceScore\":0,\"userSatisfaction\":0,\"adoptionRate\":0}','[\"quality\",\"assessment\",\"content\"]','content_analysis','[]','{}',NULL,NULL,'2025-10-18 05:31:15','2025-10-18 05:31:15');
INSERT INTO `prompt_templates` (`id`, `taskType`, `language`, `name`, `description`, `template`, `systemPrompt`, `variables`, `version`, `parentTemplateId`, `config`, `isEnabled`, `priority`, `statistics`, `effectiveness`, `tags`, `category`, `examples`, `metadata`, `createdBy`, `updatedBy`, `createdAt`, `updatedAt`) VALUES (13,'keyword_extraction','zh-CN','关键词提取','从文章内容中提取 SEO 关键词','你是一个专业的 SEO 关键词提取助手，擅长从文章中识别和提取对搜索引擎优化有价值的关键词。\n\n请从以下文章内容中提取 SEO 关键词：\n\n{{content}}\n\n要求：\n1. 提取 3-8 个最具 SEO 价值的关键词\n2. 关键词应该是用户可能搜索的词组\n3. 包含核心主题词、相关术语、长尾关键词\n4. 关键词应该具有一定的搜索量和商业价值\n5. 每个关键词控制在 2-8 个字\n6. 优先选择能提升搜索排名的关键词\n\n{{#if maxKeywords}}最多提取 {{maxKeywords}} 个关键词{{/if}}\n{{#if category}}文章类别：{{category}}{{/if}}\n{{#if title}}文章标题：{{title}}{{/if}}\n\n请直接输出关键词，用逗号分隔，不需要其他解释。\n格式示例：人工智能技术,AI应用,机器学习算法,深度学习框架','','[{\"name\":\"content\",\"type\":\"string\",\"required\":true,\"description\":\"文章内容\"},{\"name\":\"maxKeywords\",\"type\":\"number\",\"required\":false,\"description\":\"最多关键词数量\"},{\"name\":\"category\",\"type\":\"string\",\"required\":false,\"description\":\"文章类别\"},{\"name\":\"title\",\"type\":\"string\",\"required\":false,\"description\":\"文章标题\"}]','1.0.0',NULL,'{\"maxLength\":500,\"temperature\":0.7,\"topP\":0.9}',1,10,'{\"usageCount\":0,\"successCount\":0,\"failureCount\":0,\"averageScore\":0}','{\"qualityScore\":0,\"relevanceScore\":0,\"userSatisfaction\":0,\"adoptionRate\":0}','[\"content\",\"seo\",\"keywords\",\"optimization\"]','content_analysis','[{\"input\":{\"content\":\"随着人工智能技术的发展，机器学习和深度学习已经广泛应用于各个领域...\",\"maxKeywords\":6,\"title\":\"AI 技术在现代企业中的应用\"},\"output\":\"人工智能技术,机器学习应用,深度学习,AI企业应用,智能化转型,AI解决方案\"}]','{}',NULL,NULL,'2025-10-18 14:05:18','2025-10-18 14:05:18');
INSERT INTO `prompt_templates` (`id`, `taskType`, `language`, `name`, `description`, `template`, `systemPrompt`, `variables`, `version`, `parentTemplateId`, `config`, `isEnabled`, `priority`, `statistics`, `effectiveness`, `tags`, `category`, `examples`, `metadata`, `createdBy`, `updatedBy`, `createdAt`, `updatedAt`) VALUES (16,'image_prompt_optimization','zh-CN','图片生成提示词优化','将用户的简单描述转换为详细的图片生成提示词','你是一位专业的AI图片生成提示词专家。请根据用户提供的简单描述，生成一个详细、具体的图片生成提示词，要求如下：Flat vector illustration, modern tech style, clean and bright color palette dominated by light blue and white, with accents of orange and yellow, clear outlines, minimalist shading, no gradients, balanced composition, professional and vibrant visual effect, suitable for business and technology themes, 4K resolution, high detail。\n\n要求：\n(扁平插画, 矢量风, 高饱和色块, 柔和渐变光影, 清晰描边),\n科技主题场景, 角色Q版卡通, 圆润五官, 简洁服装,\n屏幕与界面元素, 数据图表曲线, 霓虹粒子特效, 放射能量线,\n蓝橙黄为主色, 点缀薄荷绿与紫, 暖冷对比背景,\n干净桌面/设备/芯片/城市/太空元素, 叙事感强, 明亮氛围\n\n\n用户描述：{{userInput}}\n\n优化后的提示词：','你是一位专业的AI图片生成提示词专家，擅长将简单描述转换为详细的图片生成提示词。','[{\"name\":\"userInput\",\"type\":\"string\",\"required\":true,\"description\":\"用户提供的简单图片描述\"}]','1.0.0',NULL,'{\"maxLength\":300,\"temperature\":0.7,\"topP\":0.9}',1,10,NULL,NULL,'[\"图片生成\",\"提示词优化\",\"文生图\",\"image-generation\"]','image_generation','[{\"input\":{\"userInput\":\"一只猫\"},\"output\":\"一只优雅的橘色短毛猫，蜷缩在温暖的阳光下，柔和的自然光从窗户洒在它的毛发上，产生金色的光晕，背景是简约的现代家居环境，景深效果突出主体，专业摄影，高清画质。\"},{\"input\":{\"userInput\":\"未来城市\"},\"output\":\"赛博朋克风格的未来都市夜景，高耸入云的摩天大楼上布满霓虹灯广告牌，飞行器在空中穿梭，地面潮湿的街道反射着五彩斑斓的光芒，浓重的科技感与工业风格，电影级构图，超现实主义，8K分辨率。\"}]',NULL,NULL,NULL,'2025-10-21 15:25:17','2025-10-21 15:31:38');
INSERT INTO `prompt_templates` (`id`, `taskType`, `language`, `name`, `description`, `template`, `systemPrompt`, `variables`, `version`, `parentTemplateId`, `config`, `isEnabled`, `priority`, `statistics`, `effectiveness`, `tags`, `category`, `examples`, `metadata`, `createdBy`, `updatedBy`, `createdAt`, `updatedAt`) VALUES (17,'image_prompt_optimization','en-US','Image Generation Prompt Optimization','Convert user\'s simple description into detailed image generation prompt','You are a professional AI image generation prompt expert. Please convert the user\'s simple description into a detailed and specific image generation prompt.\n\nRequirements:\n1. Include elements such as subject, scene, style, lighting, and color\n2. Use professional photography or art terminology\n3. Be specific and vivid, avoid abstract and vague descriptions\n4. Keep the length between 50-200 words\n5. Return only the optimized prompt without additional explanations\n\nUser description: {{userInput}}\n\nOptimized prompt:','You are a professional AI image generation prompt expert, skilled in converting simple descriptions into detailed image generation prompts.','[{\"name\":\"userInput\",\"type\":\"string\",\"required\":true,\"description\":\"User\'s simple image description\"}]','1.0.0',NULL,'{\"maxLength\":300,\"temperature\":0.7,\"topP\":0.9}',1,10,NULL,NULL,'[\"image-generation\",\"prompt-optimization\",\"text-to-image\"]','image_generation','[{\"input\":{\"userInput\":\"a cat\"},\"output\":\"An elegant orange short-haired cat, curled up in warm sunlight, soft natural light streaming through the window creating a golden halo on its fur, simple modern home interior background, shallow depth of field highlighting the subject, professional photography, high-definition quality.\"},{\"input\":{\"userInput\":\"futuristic city\"},\"output\":\"Cyberpunk-style futuristic city night scene, towering skyscrapers covered with neon advertising boards, flying vehicles shuttling through the air, wet streets reflecting colorful lights, heavy tech and industrial style, cinematic composition, surrealism, 8K resolution.\"}]',NULL,NULL,NULL,'2025-10-21 15:25:17','2025-10-21 15:31:38');
INSERT INTO `roles` (`id`, `roleName`, `roleCode`, `roleDesc`, `status`, `menus`, `buttons`, `createBy`, `createdAt`, `updateBy`, `updatedAt`) VALUES (1,'超级管理员','R_SUPER_ADMIN','超级管理员','1','[1,2,3,4,5,7,8,9,10,15,17,18,41,19,21,22,23,24,26,27,28,37,40]','[\"sitemap.status\",\"sitemap.refresh\",\"sitemap.cache\",\"sitemap.preview\",\"sitemap.config\",\"sitemap.configPut\",\"sitemap.test\",\"admins.login\",\"admins.status\",\"admins.init\",\"admins.me\",\"admins.routes\",\"admins.logout\",\"admins.list\",\"admins.post\",\"admins.put\",\"admins.delete\",\"roles.list\",\"roles.all\",\"roles.post\",\"roles.put\",\"roles.delete\",\"menus.list\",\"menus.post\",\"menus.put\",\"menus.delete\",\"menus.reorder\",\"menus.status\",\"ads.list\",\"ads.detail\",\"ads.post\",\"ads.put\",\"ads.delete\",\"logs.list\",\"logs.delete\",\"logs.all\",\"system.config\",\"system.configPost\",\"system.configDelete\",\"files.list\",\"files.put\",\"files.delete\",\"categories.list\",\"categories.detail\",\"categories.post\",\"categories.put\",\"categories.delete\",\"content.list\",\"content.detail\",\"content.post\",\"content.put\",\"content.delete\",\"content.batch\",\"content.top\",\"content.pin\",\"content.assignments\",\"content.editor\",\"content.category\",\"tags.list\",\"tags.detail\",\"tags.post\",\"tags.put\",\"tags.delete\",\"messages.list\",\"messages.detail\",\"messages.post\",\"messages.delete\",\"messages.state\",\"messages.stats\",\"messages.audit\",\"messages.auditPut\",\"users.list\",\"users.detail\",\"users.put\",\"users.delete\",\"mailTemplates.list\",\"mailTemplates.types\",\"mailTemplates.detail\",\"mailTemplates.post\",\"mailTemplates.put\",\"mailTemplates.delete\",\"templates.list\",\"templates.detail\",\"templates.active\",\"templates.post\",\"templates.put\",\"templates.delete\",\"templates.batch\",\"templates.activate\",\"templates.deactivate\",\"templates.remote\",\"templates.install\",\"templates.installDelete\",\"templates.export\",\"templates.check\",\"templates.fi